export const CANONICAL_DECISIONS: readonly Decision[] = [
  {
    "id": "DEC-001",
    "date": "2026-09-03",
    "decision": "Use a non-binding EOI/RFP rather than a purchase LOI.",
    "status": "Current",
    "rationale": "No confirmed buyer entity, model mix, quantity, landed cost, or financing exists."
  },
  {
    "id": "DEC-002",
    "date": "2026-09-03",
    "decision": "Request approximately 10 candidate models and support packages.",
    "status": "Current",
    "rationale": "The supplier should respond to a bounded portfolio instead of an unrestricted catalogue request."
  },
  {
    "id": "DEC-003",
    "date": "2026-09-03",
    "decision": "Run supplier discovery, local evidence gathering, and minimum service planning in parallel.",
    "status": "Current",
    "rationale": "Service readiness cannot be postponed until after uncontrolled vehicle sales."
  },
  {
    "id": "DEC-004",
    "date": "2026-09-03",
    "decision": "Treat Diallo as proposed Mauritania market-development lead.",
    "status": "Current",
    "rationale": "Partnership, equity, exclusivity, and appointment must follow measurable contribution and written agreement."
  },
  {
    "id": "DEC-005",
    "date": "2026-09-03",
    "decision": "Launch the portal first as a non-binding demand-validation surface.",
    "status": "Current",
    "rationale": "Public interest can inform the shortlist before inventory is acquired."
  },
  {
    "id": "DEC-006",
    "date": "2026-09-03",
    "decision": "Separate automotive, gold, and smart-city lanes.",
    "status": "Current",
    "rationale": "Each has distinct economics, risk, authority, and compliance requirements."
  },
  {
    "id": "DEC-007",
    "date": "2026-09-06",
    "decision": "Re-weight the Senegal thesis from vehicle sales toward service, parts, training, and quality assurance.",
    "status": "Current",
    "rationale": "Senegal raised import age limits to 10/15 years (Oct 2025); ~80% of its fleet is 10+ years old; parts distribution is fragmented with no firm above 10% share. The service layer is less contested and needs no OEM authorization."
  },
  {
    "id": "DEC-008",
    "date": "2026-09-06",
    "decision": "Build the workshop and technician registry as the first Phase 0 asset.",
    "status": "Current",
    "rationale": "No such register exists in either country. It answers sprint questions 15-16, creates a locally owned data asset, and is the credential that makes OEM and institutional conversations serious."
  },
  {
    "id": "DEC-009",
    "date": "2026-09-06",
    "decision": "No customer deposits, investor solicitation, returns language, or public investment page until one full commercial loop is proven and counsel has opined.",
    "status": "Current",
    "rationale": "Mauritania and Senegal sit in different securities and monetary regimes, and diaspora solicitation adds each investor's home jurisdiction. Exposure is asymmetric and irreversible."
  },
  {
    "id": "DEC-010",
    "date": "2026-09-06",
    "decision": "Source Islamic finance from a licensed local institution rather than replicating murabaha or ijara in-house.",
    "status": "Current",
    "rationale": "Moves the licensing burden to a counterparty that already carries it."
  },
  {
    "id": "DEC-011",
    "date": "2026-09-06",
    "decision": "Add a data-rights clause to the supplier EOI/RFP before responses arrive.",
    "status": "Current",
    "rationale": "Customer records, VIN histories, and telematics are the corridor's durable asset. The clause must be inserted while the program still has the freedom to insist."
  },
  {
    "id": "DEC-012",
    "date": "2026-09-06",
    "decision": "Size driver-to-owner payments against evidenced driver net earnings, with SPV-carried maintenance and a documented cure period.",
    "status": "Current",
    "rationale": "The Moove precedent shows what happens when recovery schedules drive payment design: defaults, repossessions, and reputational damage."
  },
  {
    "id": "DEC-013",
    "date": "2026-09-06",
    "decision": "Build the agent skill layer in gate-first order: language gate and evidence clerk before any production skill.",
    "status": "Current",
    "rationale": "Language and evidence errors are the only class of mistake in this program that cannot be walked back."
  },
  {
    "id": "DEC-014",
    "date": "2026-09-06",
    "decision": "New vehicles only for market entry; certified used deferred until HAMAL provenance is live and the minimum-value schedule is in hand.",
    "status": "Current",
    "rationale": "Used vehicles carry unknown landed cost until port clearance because Mauritania values them on an administrative minimum. Supersedes the v1.0 reading that age-limit removal strengthened the used lane."
  },
  {
    "id": "DEC-015",
    "date": "2026-09-06",
    "decision": "Marine Foundation sits outside the ownership chain, not above it. Redraw the entity diagram before any external use.",
    "status": "Current",
    "rationale": "A foundation shown as parent of the commercial holding company is exactly the \"foundation fronting a car business\" picture the project's own red team warns against."
  },
  {
    "id": "DEC-016",
    "date": "2026-09-06",
    "decision": "Senegal's first action is to establish who supplies and services the FDTT / BCI SN 1,000-hybrid-taxi programme, not to design a taxi pilot.",
    "status": "Current",
    "rationale": "That programme is the corridor's own Senegal thesis, already funded, with the first 100 vehicles landing February 2026 and no supplier publicly named. Senegal is not greenfield."
  },
  {
    "id": "DEC-017",
    "date": "2026-09-06",
    "decision": "Customer deposits must be refundable and escrowed, and only after counsel. Strike non-refundable deposit language.",
    "status": "Current",
    "rationale": "Non-refundable consumer deposits raise consumer-protection and deposit-taking exposure; escrow and non-refundability are in tension by design."
  },
  {
    "id": "DEC-018",
    "date": "2026-09-06",
    "decision": "Strike guarantor networks from the driver-default design.",
    "status": "Current",
    "rationale": "Guarantor networks push default risk onto the driver's family and community, failing the project's own anti-extraction test at questions 6 and 9."
  },
  {
    "id": "DEC-019",
    "date": "2026-09-06",
    "decision": "Assume no investment-code incentive relief on vehicle trading or leasing in the economics model.",
    "status": "Current",
    "rationale": "APIM reportedly excludes goods-for-resale and banking-governed leasing from incentive coverage."
  },
  {
    "id": "DEC-020",
    "date": "2026-09-06",
    "decision": "Adopt the Six Hard Gates, with Gate 1 amended so that documented confirmation that no government mandate exists is an acceptable outcome.",
    "status": "Current",
    "rationale": "As originally written, Gate 1 creates pressure to overstate government endorsement."
  },
  {
    "id": "DEC-021",
    "date": "2026-09-06",
    "decision": "Promote the reviewed 36-claim, 20-decision predecessor package as the successor canonical baseline only with explicit approval from Major Dream Williams, while preserving the previous GitHub baseline in Git history. DEC-021 brings the current register total to 21 decisions.",
    "status": "Current",
    "rationale": "Major Dream Williams explicitly authorized the controlled reconciliation and promotion on 2026-09-06. This recorded approval prevents a newer attachment from becoming authoritative merely by being newer."
  }
];

